 page.on('requestfailed',r=>failed.push(r.url()+' '+r.failure()?.errorText));
 await page.route('**/index.html',async route=>{
   const response=await route.fetch(); let html=await response.text();
   html=html.replace('init();draw();','window.__gameTest={get:()=>({state,elapsed,kills,soulsCount,level,xp,xpNeed,bossName:boss?.name||null,monsters:monsters.length,bullets:bullets.length}),addSoul:(val,x=player.x,y=player.y)=>souls.push({x,y,val}),setElapsed:v=>elapsed=v,dropBoss:()=>boss=null,update};init();draw();');
   await route.fulfill({response,body:html});
 });
 await page.goto('http://localhost:3002/');
 const start=page.locator('#startBtn');
 await start.click();
 await page.waitForTimeout(500);
 const began=await page.evaluate(()=>({intro:document.querySelector('#intro').classList.contains('hidden'),state:window.__gameTest.get().state,canvas:document.querySelector('canvas').getBoundingClientRect().toJSON()}));
 await page.keyboard.press('Space'); await page.waitForTimeout(450);
 const fired=await page.evaluate(()=>window.__gameTest.get().bullets>0);
 await page.evaluate(()=>{window.__gameTest.addSoul(8);window.__gameTest.update(.016)});
 await page.waitForTimeout(50);
 const level=await page.evaluate(()=>({snap:window.__gameTest.get(),shown:!document.querySelector('#levelOverlay').classList.contains('hidden'),choices:document.querySelectorAll('#choices .choice').length}));
 await page.locator('#choices .choice').first().click();
 await page.waitForTimeout(50);
 const resumed=await page.evaluate(()=>({state:window.__gameTest.get().state,hidden:document.querySelector('#levelOverlay').classList.contains('hidden')}));
 await page.evaluate(()=>{window.__gameTest.setElapsed(45.1);window.__gameTest.update(.016)});
 const boss1=await page.evaluate(()=>({name:window.__gameTest.get().bossName,shown:document.querySelector('#bossbar').classList.contains('show')}));
 await page.evaluate(()=>{window.__gameTest.dropBoss();window.__gameTest.setElapsed(146);window.__gameTest.update(.016)});
 const boss2=await page.evaluate(()=>window.__gameTest.get().bossName);
 const favicon=await page.locator('link[rel="icon"]').getAttribute('href');
 const desktop={began,fired,level,resumed,boss1,boss2,favicon,errors,failed};
 const mobileCtx=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
 const mobile=await mobileCtx.newPage();mobile.on('pageerror',e=>errors.push('mobile: '+String(e)));
 await mobile.goto('http://localhost:3002/');
 const controls=await mobile.evaluate(()=>({shell:document.querySelector('.game-shell').getBoundingClientRect().toJSON(),stick:getComputedStyle(document.querySelector('#stick')).display,fire:getComputedStyle(document.querySelector('#fireBtn')).display,fireRect:document.querySelector('#fireBtn').getBoundingClientRect().toJSON()}));
 await mobile.locator('#startBtn').tap();
 await mobile.locator('#fireBtn').tap();
 await mobile.waitForTimeout(100);
 const touchFire=await mobile.evaluate(()=>({intro:document.querySelector('#intro').classList.contains('hidden'),state:window.__gameTest?.get?.().state||'playing',stick:getComputedStyle(document.querySelector('#stick')).display}));
 await browser.close();
 console.log(JSON.stringify({desktop,mobile:{controls,touchFire},errors,failed},null,2));
})().catch(e=>{console.error(e);process.exit(1)});
EOF
